using System.Windows; namespace CloudServer; public partial class UserDialog:Window { public string UserName=>UserBox.Text.Trim(); public string DisplayName=>NameBox.Text.Trim(); public string Password=>PasswordBox.Password; public long QuotaBytes{get;private set;} public UserDialog(){InitializeComponent();UnlimitedBox.Checked+=(_,__)=>Toggle();UnlimitedBox.Unchecked+=(_,__)=>Toggle();SaveButton.Click+=(_,__)=>Save();} void Toggle(){QuotaBox.IsEnabled=UnitBox.IsEnabled=UnlimitedBox.IsChecked!=true;} void Save(){if(string.IsNullOrWhiteSpace(UserName)||string.IsNullOrWhiteSpace(Password)){MessageBox.Show("Benutzername und Passwort sind erforderlich.");return;}if(UnlimitedBox.IsChecked==true)QuotaBytes=0;else {if(!decimal.TryParse(QuotaBox.Text,out var q)||q<=0){MessageBox.Show("Bitte eine gültige Kapazität eingeben.");return;}decimal factor=UnitBox.SelectedIndex==1?1099511627776m:1073741824m;QuotaBytes=(long)Math.Min(q*factor,long.MaxValue);}DialogResult=true;} }